// Writes kamiya-cases.json: inflected forms generated by kamiya-codec (public domain, Unlicense),
// each paired with the dictionary form and word class the deinflector should recover,
// as rows of [inflected form, dictionary form, word class].
// kamiya-codec only serves as an oracle for test cases; the rules cite their own sources.
// It treats する compounds such as 勉強する as godan verbs, so only する itself is included.
// Forms that the deinflector leaves to lookup are left out: the full subsidiary verbs ている, ておく and てしまう
// (their contractions てる, とく and ちゃう stay), で after ない, the short causative, and the nominal さ of adjectives.
//
// Install kamiya-codec outside the repository, then run this script from the repository root:
//   mise exec -- npm install --prefix /tmp/kamiya-codec kamiya-codec@4.16.1
//   NODE_PATH=/tmp/kamiya-codec/node_modules mise exec -- node crates/core/src/deinflection/japanese/fixtures/generate-kamiya-cases.cjs

const fs = require("node:fs");
const path = require("node:path");
const codec = require("kamiya-codec");

const verbs = [
  ["書く", "v5"],
  ["泳ぐ", "v5"],
  ["話す", "v5"],
  ["待つ", "v5"],
  ["死ぬ", "v5"],
  ["遊ぶ", "v5"],
  ["読む", "v5"],
  ["帰る", "v5"],
  ["買う", "v5"],
  ["行く", "v5"],
  ["食べる", "v1"],
  ["見る", "v1"],
  ["起きる", "v1"],
  ["する", "vs"],
  ["来る", "vk"],
  ["くる", "vk"],
];

const plainConjugations = [
  "Negative",
  "Conditional",
  "Imperative",
  "Volitional",
  "Te",
  "Ta",
  "Tara",
  "Tari",
  "Zu",
  "Nu",
];

const auxiliaryChains = [
  ["Masu"],
  ["Nai"],
  ["Tai"],
  ["Potential"],
  ["ReruRareru"],
  ["SeruSaseru"],
  ["CausativePassive"],
  ["TeIru"],
  ["Oku"],
  ["Shimau"],
  ["SeruSaseru", "ReruRareru"],
  ["Potential", "Nai"],
  ["ReruRareru", "Tai"],
];

const chainConjugations = [
  "Dictionary",
  "Negative",
  "Ta",
  "Te",
  "Conditional",
  "Tara",
];

const adjectives = ["高い", "若い", "悲しい", "美味しい"];

const adjectiveConjugations = [
  "Negative",
  "Past",
  "NegativePast",
  "ConjunctiveTe",
  "Adverbial",
  "Conditional",
  "TaraConditional",
  "StemSou",
  "StemNegativeSou",
];

/**
 * Leaves out the potentials that kamiya-codec gives as すれる and くれる where the sources give できる and こ(ら)れる,
 * and the negative of ない, which kamiya-codec gives as なくはない, with the particle は.
 */
function isSupported([term], auxiliaries, conjugation) {
  const isMisformedPotential =
    ["する", "くる"].includes(term) && auxiliaries.includes("Potential");
  const isNegatedNai =
    auxiliaries.at(-1) === "Nai" && conjugation === "Negative";
  return !isMisformedPotential && !isNegatedNai;
}

function verbCases() {
  return verbs.flatMap((verb) => [
    ...plainConjugations.flatMap((conjugation) =>
      verbForms(verb, [], conjugation),
    ),
    ...auxiliaryChains.flatMap((auxiliaries) =>
      chainConjugations
        .filter((conjugation) => isSupported(verb, auxiliaries, conjugation))
        .flatMap((conjugation) => verbForms(verb, auxiliaries, conjugation)),
    ),
  ]);
}

function verbForms([term, wordClass], auxiliaries, conjugation) {
  const forms = conjugateOrSkip(term, auxiliaries, conjugation, wordClass);
  return completeForms(forms).map((inflected) => [inflected, term, wordClass]);
}

/** Returns no forms for the combinations that kamiya-codec does not handle, such as a passive volitional. */
function conjugateOrSkip(term, auxiliaries, conjugation, wordClass) {
  try {
    return codec.conjugateAuxiliaries(
      term,
      auxiliaries,
      conjugation,
      wordClass === "v1",
    );
  } catch {
    return [];
  }
}

function adjectiveCases() {
  return adjectives.flatMap((term) =>
    adjectiveConjugations.flatMap((conjugation) =>
      completeForms(codec.adjConjugate(term, conjugation, true)).map(
        (inflected) => [inflected, term, "adj-i"],
      ),
    ),
  );
}

/**
 * Drops the bare stems that kamiya-codec lists beside some forms (書か beside 書かない),
 * the doubled endings it produces for some irregular forms (しようう), its ぢまう where the sources give じまう,
 * the copula after そう, the full subsidiary verbs after the te-form, and the particle で after ない.
 */
function completeForms(forms) {
  return forms
    .filter(
      (form) =>
        !forms.some((other) => other !== form && other.startsWith(form)),
    )
    .filter((form) => !/(うう|ずず|ぬぬ)$/.test(form) && !form.includes("ぢま"))
    .filter(
      (form) => !/[てで](い|お|しま)/.test(form) && !form.endsWith("ないで"),
    )
    .map((form) => form.replace(/そうだ$/, "そう"));
}

function uniqueCases(cases) {
  const seen = new Set();
  return cases.filter((testCase) => {
    const key = testCase.join("\t");
    const isNew = !seen.has(key);
    seen.add(key);
    return isNew;
  });
}

const cases = uniqueCases([...verbCases(), ...adjectiveCases()]);
const output = path.join(__dirname, "kamiya-cases.json");
const rows = cases.map(
  (row) => `  [${row.map((cell) => JSON.stringify(cell)).join(", ")}]`,
);
fs.writeFileSync(output, `[\n${rows.join(",\n")}\n]\n`);
console.log(`Wrote ${cases.length} cases to ${output}`);
